package exactcompiler

import (
	"github.com/microsoft/TypeScript/tsc/internal/ast"
	"github.com/microsoft/TypeScript/tsc/internal/checker"
)

// componentBindingInferenceValues gives the checker the finite value props generated by
// shorthand. Enhancement-only names do not contribute component generic inference.
func componentBindingInferenceValues(node *ast.Node, signature *checker.Signature, typeChecker *checker.Checker) []checker.ExactJsxBindingInference {
	props := typeChecker.GetTypeOfSymbol(signature.Parameters()[0])
	values := []checker.ExactJsxBindingInference{}
	for _, property := range node.Attributes().AsJsxAttributes().Properties.Nodes {
		if !ast.IsJsxAttribute(property) {
			continue
		}
		attribute := property.AsJsxAttribute()
		if !ast.IsJsxNamespacedName(attribute.Name()) || attribute.Initializer == nil || !ast.IsJsxExpression(attribute.Initializer) {
			continue
		}
		pair := attribute.Name().AsJsxNamespacedName()
		if typeChecker.GetPropertyOfType(props, pair.Namespace.Text()) == nil || typeChecker.GetPropertyOfType(props, pair.Name().Text()) == nil {
			continue
		}
		target := attribute.Initializer.AsJsxExpression().Expression
		if target != nil {
			values = append(values, checker.ExactJsxBindingInference{Name: pair.Namespace.Text(), Value: target})
		}
	}
	return values
}
